UPDATE ai_transform_modes
SET name = #{name},
    description = #{description},
    enabled = #{enabled},
    sort_order = #{sortOrder},
    updated_at = NOW(6)
WHERE id = #{id}
  AND current_version = #{currentVersion}
  AND updated_at = #{updatedAt}

UPDATE ai_transform_modes
SET current_version = #{newVersion}
WHERE id = #{id}
  AND current_version = #{expectedVersion}
